(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.2)*12;
  const w1y = Math.cos(y*0.016-t*0.25)*18+Math.sin(x*0.015+t*0.35)*12;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*10+Math.cos((y+w1y)*0.01+t*0.18)*8;
  const w2y = Math.cos((y+w1y)*0.011+t*0.12)*10+Math.sin((x+w1x)*0.009-t*0.2)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+2)*40,0.14,1.3,0.7],
    [400+Math.cos(t*0.55+1)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8,1.05]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2),decay=1/(1+d*0.003);
    aS+=Math.sin(d*f-t*sp)*w*decay;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*decay;
    hrm+=Math.sin(d*f*0.5-t*sp*0.3+0.8)*w*decay*0.5;
  }
  const act=aS/8,inh=iS/8,h=hrm/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.07+t*0.5)*Math.cos(sy*0.06-t*0.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.03-ang*2-t*0.8)*0.2;
  const c2x=360+Math.sin(t*0.2)*60,c2y=80+Math.cos(t*0.25)*40;
  const d2=Math.sqrt((sx-c2x)**2+(sy-c2y)**2),a2=Math.atan2(sy-c2y,sx-c2x);
  const sp2=Math.sin(d2*0.06+a2*3-t*1.8)*0.25;
  const feed=act-inh*0.7+bg*0.3+spiral+sp2+h*0.4;
  const reaction=Math.tanh(feed*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const detail=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)*0.1*Math.abs(reaction);
  const blend=reaction*0.65+cell*0.2+detail*0.15,v=blend*0.5+0.5;
  const pal=[[10,15,55],[15,55,85],[20,110,120],[45,160,145],[140,190,100],[220,195,60],[230,140,65],[210,85,70],[160,50,70],[90,25,65],[40,15,55],[10,15,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const eS=Math.abs(reaction),edge=eS>0.6?1+(eS-0.6)*0.4:1;
  const sh=h*0.03;
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f+sh*30)*lum*edge))|0,Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f+sh*20)*lum*edge))|0,Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f-sh*15)*lum*edge))|0];
}
